/* Geodesic — competition physics mock papers. Generated by src/pcomp/build.py: every numerical answer was computed from the data in the question. */
WL.pcP({"tier": "r0", "kind": "mc", "mins": 60, "sections": [{"name": "", "items": [{"t": "mc", "lv": 1, "q": "A car accelerates uniformly from rest to 20 m s⁻¹ in 8.0 s. How far does it travel in that time?", "ch": ["40 m", "80 m", "160 m", "2.5 m", "320 m"], "a": 1, "hint": "", "sol": "Average speed 10 m s⁻¹ for 8.0 s: 80 m."}, {"t": "mc", "lv": 1, "q": "A 1200 kg car brakes from 25 m s⁻¹ to rest in 50 m. What is the average braking force?", "ch": ["600 N", "3750 N", "7500 N", "15 000 N", "30 000 N"], "a": 2, "hint": "", "sol": "a = v²/(2s) = 625/100 = 6.25 m s⁻², so F = 1200 × 6.25 = 7500 N."}, {"t": "mc", "lv": 1, "q": "A 0.50 kg ball is dropped from 20 m and hits the ground at 18 m s⁻¹. How much energy was transferred by air resistance? g = 10 N kg⁻¹.", "ch": ["9.5 J", "19 J", "81 J", "100 J", "181 J"], "a": 1, "hint": "", "sol": "Potential energy lost: 0.50 × 10 × 20 = 100 J. Kinetic energy gained: ½ × 0.50 × 18² = 81 J. The difference, 19 J, went to the air."}, {"t": "mc", "lv": 1, "q": "A 70 kg climber ascends 300 m in 10 minutes. What is her average useful power? g = 10 N kg⁻¹.", "ch": ["35 W", "210 W", "350 W", "2100 W", "21 000 W"], "a": 2, "hint": "", "sol": "70 × 10 × 300 = 210 kJ in 600 s: 350 W."}, {"t": "mc", "lv": 1, "q": "A 3.0 kg trolley at 4.0 m s⁻¹ couples to a 1.0 kg trolley at rest. What is their common speed?", "ch": ["1.0 m s⁻¹", "2.0 m s⁻¹", "3.0 m s⁻¹", "4.0 m s⁻¹", "12 m s⁻¹"], "a": 2, "hint": "", "sol": "Momentum 12 kg m s⁻¹ shared by 4.0 kg: 3.0 m s⁻¹."}, {"t": "mc", "lv": 2, "q": "A 0.20 kg mass on a 0.50 m string is whirled in a horizontal circle at 3.0 m s⁻¹ (ignore gravity). What is the tension?", "ch": ["0.30 N", "1.2 N", "1.8 N", "3.6 N", "7.2 N"], "a": 3, "hint": "", "sol": "T = mv²/r = 0.20 × 9.0/0.50 = 3.6 N."}, {"t": "mc", "lv": 2, "q": "A steel wire 2.0 m long with cross-section 1.0 mm² stretches by 1.0 mm under a 100 N load. What is the Young modulus of the steel?", "ch": ["5 × 10¹⁰ Pa", "1 × 10¹¹ Pa", "2 × 10¹¹ Pa", "2 × 10⁸ Pa", "5 × 10⁴ Pa"], "a": 2, "hint": "", "sol": "Stress = 100/(1.0 × 10⁻⁶) = 1.0 × 10⁸ Pa; strain = 1.0 × 10⁻³/2.0 = 5 × 10⁻⁴; E = stress/strain = 2 × 10¹¹ Pa."}, {"t": "mc", "lv": 1, "q": "What is the total pressure 20 m below the surface of a lake? Atmospheric pressure is 1.0 × 10⁵ Pa, water density 1000 kg m⁻³, g = 10 N kg⁻¹.", "ch": ["2.0 × 10⁵ Pa", "3.0 × 10⁵ Pa", "1.2 × 10⁵ Pa", "2.1 × 10⁵ Pa", "3.0 × 10⁶ Pa"], "a": 1, "hint": "", "sol": "ρgh = 1000 × 10 × 20 = 2.0 × 10⁵ Pa, plus the atmosphere: 3.0 × 10⁵ Pa."}, {"t": "mc", "lv": 1, "q": "A 2.0 kW kettle runs on a 230 V supply. Roughly what current does it draw?", "ch": ["0.11 A", "4.3 A", "8.7 A", "17 A", "460 A"], "a": 2, "hint": "", "sol": "I = P/V = 2000/230 ≈ 8.7 A."}, {"t": "mc", "lv": 2, "q": "A wire is stretched to twice its length without changing its volume. By what factor does its resistance change?", "ch": ["×½", "×1", "×2", "×4", "×8"], "a": 3, "hint": "", "sol": "R = ρL/A. The length doubles and, with the volume fixed, the area halves: ×4."}, {"t": "mc", "lv": 2, "q": "Two 4.0 Ω resistors in parallel are connected to a 6.0 V cell with internal resistance 1.0 Ω. What current does the cell supply?", "ch": ["0.67 A", "1.0 A", "1.5 A", "2.0 A", "3.0 A"], "a": 3, "hint": "", "sol": "The pair gives 2.0 Ω; with the internal resistance, 3.0 Ω in all: I = 6.0/3.0 = 2.0 A."}, {"t": "mc", "lv": 2, "q": "A potential divider is a fixed 1 kΩ resistor in series with a light-dependent resistor (LDR), across a battery. The output is taken across the LDR. What happens to the output voltage as the light gets brighter?", "ch": ["It rises", "It falls", "It stays the same", "It changes sign", "It doubles"], "a": 1, "hint": "", "sol": "Brighter light lowers the LDR’s resistance, so it takes a smaller share of the battery voltage."}, {"t": "mc", "lv": 1, "q": "A wave has frequency 50 Hz and wavelength 6.0 m. What is its speed?", "ch": ["8.3 m s⁻¹", "56 m s⁻¹", "120 m s⁻¹", "300 m s⁻¹", "3000 m s⁻¹"], "a": 3, "hint": "", "sol": "v = fλ = 50 × 6.0 = 300 m s⁻¹."}, {"t": "mc", "lv": 2, "q": "A string 0.60 m long, fixed at both ends, vibrates in its third harmonic at 300 Hz. What is the speed of waves on the string?", "ch": ["60 m s⁻¹", "120 m s⁻¹", "180 m s⁻¹", "360 m s⁻¹", "540 m s⁻¹"], "a": 1, "hint": "", "sol": "Three half-wavelengths fit in 0.60 m, so λ = 0.40 m and v = 300 × 0.40 = 120 m s⁻¹."}, {"t": "mc", "lv": 2, "q": "Light travels from glass of refractive index 1.5 towards air. About what is the critical angle?", "ch": ["30°", "42°", "48°", "56°", "90°"], "a": 1, "hint": "", "sol": "sin c = 1/1.5 = 0.67, and sin 42° ≈ 0.67."}, {"t": "mc", "lv": 2, "q": "A grating has 300 lines per millimetre. With light of wavelength 500 nm, what is the highest order of maximum that can be seen?", "ch": ["2", "3", "5", "6", "7"], "a": 3, "hint": "", "sol": "d = 1/300 mm = 3.33 μm; d/λ = 6.7, and the order cannot exceed this: 6."}, {"t": "mc", "lv": 1, "q": "What is the energy of a photon of wavelength 620 nm? Use hc = 1240 eV nm.", "ch": ["0.5 eV", "1.0 eV", "2.0 eV", "3.1 eV", "4.0 eV"], "a": 2, "hint": "", "sol": "E = 1240/620 = 2.0 eV."}, {"t": "mc", "lv": 1, "q": "Photons of energy 4.0 eV fall on a metal with work function 2.5 eV. What is the greatest kinetic energy of the emitted electrons?", "ch": ["1.5 eV", "2.5 eV", "4.0 eV", "6.5 eV", "0"], "a": 0, "hint": "", "sol": "KE_max = hf − φ = 4.0 − 2.5 = 1.5 eV."}, {"t": "mc", "lv": 2, "q": "The activity of a sample falls from 800 Bq to 50 Bq in 24 days. What is its half-life?", "ch": ["3 days", "4 days", "6 days", "8 days", "12 days"], "a": 2, "hint": "", "sol": "800 → 400 → 200 → 100 → 50 is four half-lives in 24 days: 6 days each."}, {"t": "mc", "lv": 1, "q": "Carbon-14 decays by β⁻ emission. What is the daughter nucleus?", "ch": ["boron-14", "carbon-13", "nitrogen-14", "nitrogen-15", "oxygen-14"], "a": 2, "hint": "", "sol": "A neutron becomes a proton: the mass number stays 14 and the proton number rises from 6 to 7, nitrogen."}, {"t": "mc", "lv": 1, "q": "How much energy is needed to heat 2.0 kg of water from 20 °C to 70 °C? Specific heat capacity 4200 J kg⁻¹ K⁻¹.", "ch": ["42 kJ", "84 kJ", "210 kJ", "420 kJ", "588 kJ"], "a": 3, "hint": "", "sol": "Q = mcΔT = 2.0 × 4200 × 50 = 420 kJ."}, {"t": "mc", "lv": 1, "q": "A gas at 300 K and 1.0 × 10⁵ Pa is heated at constant volume to 450 K. What is its new pressure?", "ch": ["0.67 × 10⁵ Pa", "1.5 × 10⁵ Pa", "2.25 × 10⁵ Pa", "4.5 × 10⁵ Pa", "1.0 × 10⁵ Pa"], "a": 1, "hint": "", "sol": "p ∝ T: × 450/300 = 1.5."}, {"t": "mc", "lv": 1, "q": "A ball is thrown horizontally at 10 m s⁻¹ from the top of a 20 m cliff. How far from the base does it land? g = 10 m s⁻².", "ch": ["10 m", "14 m", "20 m", "40 m", "200 m"], "a": 2, "hint": "", "sol": "Falling 20 m takes √(2 × 20/10) = 2.0 s; in that time it moves 20 m sideways."}, {"t": "mc", "lv": 3, "q": "Roughly how many molecules of air are in a classroom 10 m × 8 m × 3 m?", "ch": ["10²³", "10²⁵", "6 × 10²⁷", "10³⁰", "10³³"], "a": 2, "hint": "", "sol": "A mole of gas at room conditions fills about 0.024 m³, so 240 m³ is 10⁴ mol, or 10⁴ × 6 × 10²³ = 6 × 10²⁷ molecules."}, {"t": "mc", "lv": 2, "q": "The speed of a wave on a string depends on the tension T and the mass per unit length μ. Which expression has the units of a speed?", "ch": ["T/μ", "√(T/μ)", "√(Tμ)", "Tμ", "√(μ/T)"], "a": 1, "hint": "", "sol": "T/μ has units N/(kg m⁻¹) = kg m s⁻² × m/kg = m² s⁻², so its square root is a speed."}]}], "rules": "One mark for each right answer and none taken off for a wrong one, so answer every question. No calculator."});
WL.pcP({"tier": "fma", "kind": "mc", "mins": 75, "sections": [{"name": "", "items": [{"t": "mc", "lv": 1, "q": "A ball is thrown straight up at 20 m s⁻¹. How high does it rise? g = 10 m s⁻².", "ch": ["10 m", "20 m", "40 m", "2 m", "200 m"], "a": 1, "hint": "", "sol": "h = v²/(2g) = 400/20 = 20 m."}, {"t": "mc", "lv": 1, "q": "A car travels 30 km at 60 km/h and then 30 km at 30 km/h. What is its average speed for the whole trip?", "ch": ["40 km/h", "45 km/h", "50 km/h", "35 km/h", "60 km/h"], "a": 0, "hint": "", "sol": "60 km in 0.5 h + 1.0 h = 1.5 h: 40 km/h. The average of the speeds, 45 km/h, is the classic wrong answer."}, {"t": "mc", "lv": 1, "q": "A block slides from rest down a frictionless 30° incline. How fast is it going after sliding 5.0 m along the incline? g = 10 m s⁻².", "ch": ["5.0 m/s", "7.1 m/s", "10 m/s", "3.5 m/s", "8.7 m/s"], "a": 1, "hint": "", "sol": "It drops 5.0 sin 30° = 2.5 m, so v = √(2 × 10 × 2.5) = 7.1 m/s."}, {"t": "mc", "lv": 1, "q": "A lift accelerates upwards at 2.0 m/s². What does a scale read under a 60 kg person standing in it? g = 10 m s⁻².", "ch": ["480 N", "600 N", "720 N", "120 N", "840 N"], "a": 2, "hint": "", "sol": "N − mg = ma, so N = 60 × (10 + 2.0) = 720 N."}, {"t": "mc", "lv": 1, "q": "Blocks of 2 kg and 3 kg touch on a frictionless floor. A 10 N push acts on the 2 kg block. What force does the 2 kg block exert on the 3 kg block?", "ch": ["4 N", "5 N", "6 N", "10 N", "2 N"], "a": 2, "hint": "", "sol": "Both accelerate at 10/5 = 2 m/s², and the 3 kg block needs 3 × 2 = 6 N."}, {"t": "mc", "lv": 1, "q": "A block on a frictionless table is tied by a string over a pulley at the edge to a hanging block of equal mass. What is the acceleration? g = 10 m s⁻².", "ch": ["0", "2.5 m/s²", "5 m/s²", "10 m/s²", "20 m/s²"], "a": 2, "hint": "", "sol": "The weight mg accelerates mass 2m: a = g/2 = 5 m/s²."}, {"t": "mc", "lv": 2, "q": "A 0.5 kg ball hits a wall at 6 m/s and rebounds at 4 m/s, in contact for 0.02 s. What is the average force on it?", "ch": ["50 N", "100 N", "150 N", "250 N", "500 N"], "a": 3, "hint": "", "sol": "Δp = 0.5 × (6 + 4) = 5 kg m/s in 0.02 s: 250 N. Forgetting that the direction reverses gives 50 N."}, {"t": "mc", "lv": 1, "q": "A 1.0 kg mass oscillates on a spring of stiffness 100 N/m. What is the period?", "ch": ["0.10 s", "0.31 s", "0.63 s", "1.0 s", "6.3 s"], "a": 2, "hint": "", "sol": "T = 2π√(m/k) = 2π/10 = 0.63 s."}, {"t": "mc", "lv": 1, "q": "A pendulum has period 2.0 s on Earth. What is its period on a planet where g is a quarter as large?", "ch": ["0.5 s", "1.0 s", "2.0 s", "4.0 s", "8.0 s"], "a": 3, "hint": "", "sol": "T ∝ 1/√g: twice as long."}, {"t": "mc", "lv": 1, "q": "A satellite’s circular orbit radius is made four times larger. By what factor does its period change?", "ch": ["2", "4", "8", "16", "64"], "a": 2, "hint": "", "sol": "T ∝ r^{3/2} = 4^{3/2} = 8."}, {"t": "mc", "lv": 2, "q": "A uniform 4.0 m plank of mass 20 kg rests on supports at its two ends. A 60 kg person stands 1.0 m from the left end. What force does the left support exert? g = 10 m s⁻².", "ch": ["350 N", "450 N", "550 N", "650 N", "800 N"], "a": 2, "hint": "", "sol": "Moments about the right end: F × 4.0 = 600 × 3.0 + 200 × 2.0, so F = 550 N."}, {"t": "mc", "lv": 2, "q": "A uniform disc and a thin hoop have the same mass and radius. Equal torques act on each from rest. What is the ratio of the disc’s angular acceleration to the hoop’s?", "ch": ["½", "1", "√2", "2", "4"], "a": 3, "hint": "", "sol": "α = τ/I, and the disc’s I = ½MR² is half the hoop’s MR²: ratio 2."}, {"t": "mc", "lv": 1, "q": "A 2.0 kg ball at 3.0 m/s hits a 2.0 kg ball at rest, head on and elastically. What is the first ball’s velocity afterwards?", "ch": ["0", "1.5 m/s", "3.0 m/s", "−3.0 m/s", "−1.5 m/s"], "a": 0, "hint": "", "sol": "Equal masses in an elastic head-on collision swap velocities: the first ball stops."}, {"t": "mc", "lv": 1, "q": "A 5 kg box slides 4 m across a floor with μₖ = 0.3. How much work does friction do on it? g = 10 m s⁻².", "ch": ["−6 J", "−15 J", "−60 J", "−200 J", "0"], "a": 2, "hint": "", "sol": "Friction 0.3 × 50 = 15 N acts against 4 m of motion: −60 J."}, {"t": "mc", "lv": 2, "q": "A ball is thrown horizontally at 15 m/s from a height of 45 m. How fast is it moving when it lands? g = 10 m s⁻².", "ch": ["15 m/s", "30 m/s", "33.5 m/s", "45 m/s", "22.5 m/s"], "a": 2, "hint": "", "sol": "It falls for 3 s and gains 30 m/s vertically: √(15² + 30²) = 33.5 m/s."}, {"t": "mc", "lv": 2, "q": "A car takes a flat bend of radius 40 m. The coefficient of static friction is 0.9. What is the greatest speed without skidding? g = 10 m s⁻².", "ch": ["6 m/s", "13 m/s", "19 m/s", "36 m/s", "360 m/s"], "a": 2, "hint": "", "sol": "v = √(μgr) = √360 = 19 m/s."}, {"t": "mc", "lv": 1, "q": "A 3 kg object has momentum 12 kg m/s. What is its kinetic energy?", "ch": ["4 J", "12 J", "24 J", "48 J", "72 J"], "a": 2, "hint": "", "sol": "KE = p²/(2m) = 144/6 = 24 J."}, {"t": "mc", "lv": 2, "q": "A rocket in deep space ejects gas at 2000 m/s relative to itself and burns fuel until its mass has halved. By how much does its speed increase?", "ch": ["693 m/s", "1000 m/s", "1386 m/s", "2000 m/s", "4000 m/s"], "a": 2, "hint": "", "sol": "The rocket equation: Δv = u ln(m₀/m) = 2000 ln 2 = 1386 m/s."}, {"t": "mc", "lv": 2, "q": "A uniform rod of length L, pivoted at one end, is released from rest horizontal. What is its angular acceleration at the moment of release?", "ch": ["g/L", "3g/(2L)", "2g/L", "g/(2L)", "3g/L"], "a": 1, "hint": "", "sol": "τ = mgL/2 and I = mL²/3, so α = 3g/(2L). The free end starts with acceleration 3g/2, more than g."}, {"t": "mc", "lv": 2, "q": "A mass m hangs from two identical springs of stiffness k side by side. What is the period of vertical oscillations?", "ch": ["2π√(m/k)", "2π√(2m/k)", "2π√(m/(2k))", "π√(m/k)", "4π√(m/k)"], "a": 2, "hint": "", "sol": "In parallel the stiffness is 2k: T = 2π√(m/(2k))."}, {"t": "mc", "lv": 3, "q": "A planet has the same density as the Earth but twice its radius. What is the escape speed from it? (11.2 km/s for the Earth.)", "ch": ["5.6 km/s", "11.2 km/s", "15.8 km/s", "22.4 km/s", "44.8 km/s"], "a": 3, "hint": "", "sol": "v² = 2GM/R ∝ ρR², so v ∝ R at fixed density: 22.4 km/s."}, {"t": "mc", "lv": 2, "q": "A block slides down a frictionless incline with acceleration 4 m/s². What is the angle of the incline? g = 10 m s⁻².", "ch": ["11.5°", "23.6°", "30°", "36.9°", "66.4°"], "a": 1, "hint": "", "sol": "a = g sin θ, so sin θ = 0.4 and θ = 23.6°."}, {"t": "mc", "lv": 2, "q": "A ball dropped from 1.25 m bounces back up to 0.80 m. What is the coefficient of restitution?", "ch": ["0.64", "0.80", "0.89", "0.36", "1.0"], "a": 1, "hint": "", "sol": "Speed ∝ √(height), so e = √(0.80/1.25) = √0.64 = 0.80."}, {"t": "mc", "lv": 3, "q": "A 2 kg block on a frictionless floor is attached to a wall by a spring of stiffness 200 N/m. A 0.5 kg ball of putty moving at 10 m/s hits the block and sticks. What is the amplitude of the oscillation that follows?", "ch": ["0.10 m", "0.16 m", "0.22 m", "0.50 m", "1.0 m"], "a": 2, "hint": "", "sol": "Momentum: V = 5/2.5 = 2 m/s. Then ω = √(200/2.5) = 8.94 rad/s and A = V/ω = 0.22 m. Using energy straight from the putty’s speed would wrongly include the energy lost in the sticky collision."}, {"t": "mc", "lv": 3, "q": "A uniform solid cylinder rolls without slipping. What fraction of its kinetic energy is rotational?", "ch": ["1/4", "1/3", "1/2", "2/3", "2/5"], "a": 1, "hint": "", "sol": "KE = ½mv² + ½(½mr²)(v/r)² = ½mv² + ¼mv²: the rotational part is ¼ out of ¾, one third."}]}], "rules": "One point for each right answer, with no penalty for a wrong one. Use g = 10 m/s² throughout."});
WL.pcP({"tier": "r1", "kind": "num", "mins": 120, "sections": [{"name": "Section 1", "note": "Ten short problems, each worth 5 marks. In the real paper you choose which to answer, up to a limit; here, try them all.", "items": [{"t": "num", "lv": 1, "q": "A ball is thrown vertically upwards at 15 m s⁻¹ from the edge of a roof 25 m above the ground. How long is it before the ball hits the ground? g = 9.81 m s⁻².", "a": 4.25574, "u": "s", "tol": 0.02, "hint": "Take up as positive and solve −25 = 15t − ½gt².", "sol": "4.905t² − 15t − 25 = 0, whose positive root is t = 4.256 s."}, {"t": "num", "lv": 2, "q": "A 1.2 kg mass hangs from two strings, one at 30° and one at 60° above the horizontal. Find the tension in the string at 60°. g = 9.81 m s⁻².", "a": 10.1949, "u": "N", "tol": 0.02, "hint": "The strings are at right angles to each other.", "sol": "Because the strings are perpendicular, each tension is the weight’s component along it: T₆₀ = mg sin 60° = 10.19 N (and T₃₀ = mg sin 30° = 5.886 N)."}, {"t": "num", "lv": 2, "q": "The Sun’s surface temperature is 5800 K and its radius 6.96 × 10⁸ m. Treating it as a black body, find its luminosity. σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴.", "a": 3.90592e+26, "u": "W", "tol": 0.02, "hint": "L = 4πR²σT⁴.", "sol": "L = 4π(6.96 × 10⁸)² × 5.67 × 10⁻⁸ × 5800⁴ = 3.91 × 10²⁶ W."}, {"t": "num", "lv": 2, "q": "A 100 W lamp turns 5.0 % of its power into light of wavelength 550 nm. How many photons does it emit each second? h = 6.626 × 10⁻³⁴ J s, c = 2.998 × 10⁸ m s⁻¹.", "a": 1.38436e+19, "u": "photons per second", "tol": 0.02, "hint": "Energy per second divided by energy per photon.", "sol": "Each photon carries hc/λ = 3.612 × 10⁻¹⁹ J, so 5.0 W is 1.38 × 10¹⁹ photons per second."}, {"t": "num", "lv": 2, "q": "A 2.0 μF capacitor charged to 50 V is connected across an uncharged 3.0 μF capacitor. How much energy is lost? Give it in mJ.", "a": 1.5, "u": "mJ", "tol": 0.02, "hint": "Charge is conserved; energy is not.", "sol": "Q = 100 μC shared by 5.0 μF gives 20 V. Energy falls from ½ × 2.0 μF × 50² = 2.5 mJ to ½ × 5.0 μF × 20² = 1.0 mJ: 1.5 mJ is lost, as heat and radiation in the connecting wires."}, {"t": "num", "lv": 1, "q": "A wire 2.0 m long and 0.50 mm in diameter has resistance 0.20 Ω. Find the resistivity of its metal.", "a": 1.9635e-08, "u": "Ω m", "tol": 0.02, "hint": "ρ = RA/L, with A from the diameter.", "sol": "A = π(0.25 × 10⁻³)² = 1.96 × 10⁻⁷ m², so ρ = 0.20 × A/2.0 = 1.96 × 10⁻⁸ Ω m (about that of copper)."}, {"t": "num", "lv": 2, "q": "A small source radiates sound equally in all directions. The sound level is 80 dB at 10 m. At what distance is it 60 dB?", "a": 100.0, "u": "m", "tol": 0.02, "hint": "Every 10 dB is a factor of 10 in intensity.", "sol": "20 dB less is a factor of 100 in intensity. Intensity falls as 1/r², so the distance grows tenfold: 100 m."}, {"t": "num", "lv": 2, "q": "Find the speed of a satellite in a circular orbit 600 km above the Earth’s surface. GM = 3.986 × 10¹⁴ m³ s⁻² and the Earth’s radius is 6371 km.", "a": 7561.73, "u": "m/s", "tol": 0.02, "hint": "Use the radius from the Earth’s centre.", "sol": "r = 6.971 × 10⁶ m and v = √(GM/r) = 7562 m s⁻¹."}, {"t": "num", "lv": 1, "q": "A radioactive isotope has a half-life of 5.3 years. What fraction of a sample remains after 20 years?", "a": 0.0731203, "u": "", "tol": 0.02, "hint": "N/N₀ = (½)^{t/T½}.", "sol": "(½)^{20/5.3} = 0.0731."}, {"t": "num", "lv": 2, "q": "A converging lens of focal length 15 cm forms a real image of an object placed 20 cm from it. What is the magnification?", "a": 3.0, "u": "", "tol": 0.02, "hint": "Find the image distance from the lens equation.", "sol": "1/v = 1/15 − 1/20 = 1/60, so v = 60 cm and the magnification is v/u = 3.0."}]}, {"name": "Section 2", "note": "Two longer problems, 5 marks for each part.", "items": [{"title": "Landing a ski jump", "area": "Mechanics", "level": 2, "mins": 25, "stem": "A skier leaves the end of a ramp horizontally at 25 m s⁻¹ and flies over a straight slope that falls away at 35° below the horizontal, starting at the end of the ramp. Ignore air resistance; g = 9.81 m s⁻².", "parts": [{"q": "How long is the skier in the air? Give seconds.", "a": 3.56885, "u": "s", "tol": 0.02, "sol": "Landing on the slope needs y/x = tan 35°, with x = v₀t and y = ½gt². So t = 2v₀ tan 35°/g = 3.569 s."}, {"q": "How far along the slope does the skier land? Give metres.", "a": 108.919, "u": "m", "tol": 0.02, "sol": "x = v₀t = 89.22 m horizontally, so the distance along the slope is x/cos 35° = 108.9 m."}, {"q": "How fast is the skier moving on landing? Give m s⁻¹.", "a": 43.0201, "u": "m/s", "tol": 0.02, "sol": "The vertical velocity is gt = 35.01 m s⁻¹, so the speed is √(25² + 35.01²) = 43.02 m s⁻¹."}, {"q": "At what angle to the slope does the skier land? Give degrees.", "a": 19.4704, "u": "°", "tol": 0.02, "sol": "The velocity makes tan⁻¹(v_y/vₓ) = tan⁻¹(2 tan 35°) = 54.47° with the horizontal, so 19.47° with the slope. This does not depend on the take-off speed: tan(angle to horizontal) = 2 tan(slope angle)."}], "hint": "The landing condition is that the point (x, y) lies on the slope: y = x tan 35°.", "t": "long"}, {"title": "A diving bell", "area": "Fluids", "level": 2, "mins": 25, "stem": "A diving bell is a cylinder 3.0 m tall, closed at the top and open at the bottom, with a cross-section of 2.0 m². It is lowered into the sea, keeping its air, until its top is 20 m below the surface. Sea water has density 1025 kg m⁻³, atmospheric pressure is 1.013 × 10⁵ Pa and g = 9.81 m s⁻². The air stays at a constant temperature.", "parts": [{"q": "How high does the water rise inside the bell? Give metres.", "a": 2.02656, "u": "m", "tol": 0.02, "sol": "Let x be the height of the air column. The water surface inside is at depth 20 + x, so the air pressure is p₀ + ρg(20 + x), and Boyle’s law gives [p₀ + ρg(20 + x)]x = 3.0p₀. The positive root is x = 0.9734 m, so the water rises 2.027 m."}, {"q": "What is the pressure of the trapped air? Give it in kPa.", "a": 312.193, "u": "kPa", "tol": 0.02, "sol": "p = 3.0p₀/x = 312.2 kPa, about three atmospheres."}, {"q": "What volume of air, measured at atmospheric pressure, must be pumped in to push all the water out of the bell? Give m³.", "a": 13.6982, "u": "m³", "tol": 0.02, "sol": "Full of air, the bell holds 6.0 m³ at the pressure at its open end, p₀ + ρg × 23 = 332.6 kPa. That is 19.70 m³ at atmospheric pressure, of which 6.0 m³ was there from the start: 13.70 m³ must be added."}], "hint": "Boyle’s law for the trapped air, and the pressure at the water surface inside the bell.", "t": "long"}]}], "rules": "Answers are checked to 2 %. Short problems are worth 5 marks each; each part of a long problem is worth 5 marks. A calculator is fine."});
WL.pcP({"tier": "r2", "kind": "long", "mins": 180, "sections": [{"name": "", "items": [{"title": "A cylinder rocking in a trough", "area": "Mechanics", "level": 3, "mins": 35, "stem": "A uniform solid cylinder of mass 2.0 kg and radius 0.10 m rolls without slipping inside a fixed horizontal cylindrical trough of radius 0.60 m, rocking about the lowest point. g = 9.81 m s⁻².", "parts": [{"q": "Find the period of small oscillations. Give seconds.", "a": 1.7373, "u": "s", "tol": 0.02, "sol": "Let φ be the angle of the line from the trough’s axis to the cylinder’s centre. The centre moves on a circle of radius R − r = 0.50 m with speed (R − r)φ̇, and rolling makes the cylinder spin at ω = (R − r)φ̇/r. Energy: ½m(R − r)²φ̇²(1 + ½) + mg(R − r)(1 − cos φ). For small φ this is SHM with ω₀² = 2g/(3(R − r)), so T = 2π√(3(R − r)/(2g)) = 1.737 s."}, {"q": "The cylinder is released from rest with φ = 10°. Find the greatest speed of its centre. Give m s⁻¹.", "a": 0.31521, "u": "m/s", "tol": 0.02, "sol": "mg(R − r)(1 − cos 10°) = ¾mv², so v = √(4g(R − r)(1 − cos 10°)/3) = 0.3152 m s⁻¹."}, {"q": "In that motion, what is the normal force from the trough when the cylinder passes the lowest point? Give newtons.", "a": 20.0174, "u": "N", "tol": 0.02, "sol": "The centre moves on a circle of radius 0.50 m, so N − mg = mv²/(R − r): N = 20.02 N."}], "hint": "Write the energy in terms of the angle of the centre of the cylinder, and use the rolling condition to link the spin to that angle.", "t": "long"}, {"t": "long", "bank": "hohmann"}, {"t": "long", "bank": "railrod"}, {"t": "long", "bank": "eradius"}, {"t": "long", "bank": "meanfree"}]}], "rules": "Five long problems. Each part is checked to 2 % and worth 5 marks. Write full working on paper: in the real round, the method earns most of the marks."});
WL.pcP({"tier": "usapho", "kind": "long", "mins": 90, "sections": [{"name": "Part A", "items": [{"title": "A loop falling out of a magnetic field", "area": "Electromagnetism", "level": 2, "mins": 25, "stem": "A square wire loop of side 0.20 m, mass 0.050 kg and resistance 0.40 Ω falls with its plane vertical. Its upper edge is still inside a region of uniform horizontal magnetic field of 0.80 T, perpendicular to the loop; its lower edge is below the region, where there is no field. g = 9.81 m s⁻².", "parts": [{"q": "Find the terminal speed of the loop while it is leaving the field. Give m s⁻¹.", "a": 7.66406, "u": "m/s", "tol": 0.02, "sol": "The flux falls at BLv, driving a current I = BLv/R whose force BIL on the upper edge opposes the fall. Terminal speed when B²L²v/R = mg: v = mgR/(B²L²) = 7.664 m s⁻¹."}, {"q": "What current flows at that speed? Give amperes.", "a": 3.06562, "u": "A", "tol": 0.02, "sol": "BIL = mg, so I = mg/(BL) = 3.066 A."}, {"q": "At what rate is heat produced in the loop? Give watts.", "a": 3.75922, "u": "W", "tol": 0.02, "sol": "All the lost gravitational energy becomes heat: P = mgv = 3.759 W (the same as I²R)."}, {"q": "Starting from rest just as the lower edge leaves the field, the speed approaches the terminal value exponentially. Find the time constant. Give seconds.", "a": 0.78125, "u": "s", "tol": 0.02, "sol": "m dv/dt = mg − (B²L²/R)v, so v = v_t(1 − e^{−t/τ}) with τ = mR/(B²L²) = v_t/g = 0.7812 s."}], "hint": "Only the upper edge is in the field: it alone feels a force and has an emf.", "t": "long"}, {"t": "long", "bank": "hoop"}, {"t": "long", "bank": "torricelli"}]}], "rules": "One part of the exam: three problems in 90 minutes. Each numerical answer is checked to 2 % and worth 5 marks."});
WL.pcP({"tier": "ipho", "kind": "long", "mins": 75, "sections": [{"name": "Theory", "items": [{"title": "A planet with a blanket", "area": "Thermal physics", "level": 3, "mins": 40, "stem": "A planet orbits a star of surface temperature 5772 K and radius 6.957 × 10⁸ m, at a distance of 1.496 × 10¹¹ m. It reflects 30 % of the starlight that reaches it and spins fast enough for its surface temperature to be uniform. Treat the star and the planet’s surface as black bodies at the wavelengths they emit.", "parts": [{"q": "With no atmosphere, what is the planet’s equilibrium temperature? Give kelvin.", "a": 254.584, "u": "K", "tol": 0.02, "sol": "Absorbed: (1 − A)σT_s⁴(R_s/d)²πr². Emitted: 4πr²σT⁴. So T = T_s√(R_s/(2d))(1 − A)^{1/4} = 254.6 K. The planet’s size cancels."}, {"q": "Now give it a thin atmosphere that lets all starlight through but absorbs all the infrared from the ground and re-emits it equally up and down. What is the ground temperature now? Give kelvin.", "a": 302.753, "u": "K", "tol": 0.02, "sol": "The top of the atmosphere must still emit what the planet absorbs, so the atmosphere is at 254.6 K. The ground receives starlight plus the atmosphere’s downward half: σT_g⁴ = 2σT_a⁴, so T_g = 2^{1/4} × 254.6 = 302.8 K."}, {"q": "Suppose instead the atmosphere absorbs only a fraction ε = 0.78 of the ground’s infrared (and so, by Kirchhoff’s law, emits with emissivity 0.78). Find the ground temperature. Give kelvin.", "a": 288.07, "u": "K", "tol": 0.02, "sol": "Balancing energy at the top of the atmosphere and at the ground gives σT_g⁴ = σT_e⁴ × 2/(2 − ε), where T_e is the answer to the first part. T_g = 254.6 × (2/1.22)^{1/4} = 288.1 K, close to the Earth’s mean of 288 K."}, {"q": "If the planet’s orbit were 2.0 % larger, by how many kelvin would that ground temperature fall?", "a": 2.8382, "u": "K", "tol": 0.02, "sol": "Every temperature here scales as d^{−1/2}, so T_g × (1 − 1.02^{−1/2}) = 2.84 K."}], "hint": "In each case, balance the energy flowing in and out of every layer, starting from the top of the atmosphere.", "t": "long"}, {"t": "long", "bank": "gps"}]}], "rules": "Two sections in the style of an IPhO theory problem, 75 minutes. A real theory paper is three whole problems in five hours. Each part is checked to 2 % and worth 5 marks."});
